import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Radar, Compass, Layers3, PanelsTopLeft, Telescope, FileText, Settings2, ArrowUpRight, ArrowRight, Search, Plus, Github, Star, ChevronDown, ChevronRight, Bell, BookOpen, SlidersHorizontal, Menu, X, Check, Info, ExternalLink, ShieldCheck, CircleHelp, RefreshCw, Pause, Play, Trash2, Pencil, Link2, LockKeyhole, LogOut, Download, Mail, AlertTriangle, Clock3, CheckCheck, Filter, CircleDot, Send, Building2, MoreHorizontal } from 'lucide-react';
import { api, setCsrf, list, item, navigate, number, shortNumber, date, datetime, safeUrl, track } from './api';
import { trendPresentation, scheduleExplanation, loginPresentation, sortingPresentation, productEmptyPresentation, decodeRouteSegment } from './presentation';
import './styles.css';

const AppContext = createContext(null);
const useApp = () => useContext(AppContext);
const EVENT_TYPES = { release: '版本发布', capability: '能力变化', pricing: '价格与套餐', deployment: '部署变化', issue: '问题状态', discovery: '首次发现', correction: '内容更正' };
const STATUSES = { researching: '研究中', trial: '待试用', adopted: '已采用', watching: '继续观察', rejected: '已放弃' };
const SUPPORT = { supported: '有依据', limited: '有条件', unsupported: '不支持', unknown: '待核实' };
const navItems = [{ path: 'discover', label: '发现', icon: Compass }, { path: 'entities', label: '项目与产品', icon: Layers3 }, { path: 'research', label: '我的研究', icon: PanelsTopLeft }, { path: 'watches', label: '我的跟踪', icon: Telescope }, { path: 'digests', label: '变化摘要', icon: FileText }];

function useData(path, options = {}) {
  const { revision } = useApp();
  const [state, setState] = useState({ data: null, loading: true, error: null });
  const [retry, setRetry] = useState(0);
  useEffect(() => {
    let active = true;
    if (!path) { setState({ data: null, loading: false, error: null }); return; }
    setState(old => ({ ...old, loading: true, error: null }));
    api(path).then(data => { if (active) setState({ data, loading: false, error: null }); }).catch(error => { if (active) setState({ data: null, loading: false, error }); });
    return () => { active = false; };
  }, [path, revision, retry]);
  return { ...state, retry: () => setRetry(v => v + 1) };
}

function Button({ children, variant = 'secondary', className = '', busy, type = 'button', ...props }) { return <button type={type} className={`button ${variant} ${className}`} {...props} disabled={busy || props.disabled}>{busy ? <RefreshCw size={15} className="spin" /> : null}{children}</button>; }
function Badge({ children, tone = 'neutral' }) { return <span className={`badge ${tone}`}>{children}</span>; }
function External({ href, children, className = '' }) { const url = safeUrl(href); return url ? <a href={url} target="_blank" rel="noopener noreferrer" className={className}>{children}<ArrowUpRight size={13} /></a> : <span className="muted">暂无信息</span>; }
function Empty({ title = '暂时没有内容', description = '更换筛选条件，或稍后再来看看。', action, icon: Icon = Telescope }) { return <div className="empty"><span className="empty-icon"><Icon size={25} /></span><h3>{title}</h3><p>{description}</p>{action}</div>; }
function Loading() { return <div className="loading" role="status"><RefreshCw size={18} className="spin" /><span>正在整理研究信息…</span></div>; }
function DataState({ state, children }) { if (state.loading && !state.data) return <Loading />; if (state.error) return <ErrorState error={state.error} retry={state.retry} />; return children; }
function ErrorState({ error, retry }) {
  const { session, setLogin } = useApp();
  const auth = loginPresentation(session);
  if (error.status === 401) return <Empty icon={LockKeyhole} title={auth.available ? '为你的研究留一个位置' : '当前可浏览公开研究资料'} description={auth.available ? '登录后保存研究任务、关注原因和私有判断。' : auth.reason} action={<Button onClick={() => setLogin(true)}>{auth.available ? '登录工作区' : '查看登录说明'}<ArrowRight size={15} /></Button>} />;
  if (error.status === 404) return <Empty icon={Search} title="没有找到可查看的内容" description="这条资料可能已移除，或当前账户无法查看。可以返回发现页重新选择。" action={<a className="button primary" href="#discover">返回发现页<ArrowRight size={15} /></a>} />;
  return <Empty icon={AlertTriangle} title="暂时无法加载" description={error.message} action={<Button onClick={retry}>重新加载<RefreshCw size={15} /></Button>} />;
}
function Field({ label, help, children, wide }) { const labelId = React.useId(); return <label className={`field ${wide ? 'wide' : ''}`}><span id={labelId}>{label}</span>{React.isValidElement(children) ? React.cloneElement(children, { 'aria-labelledby': labelId, ...(help ? { 'aria-describedby': `${labelId}-help` } : {}) }) : children}{help && <small id={`${labelId}-help`}>{help}</small>}</label>; }
function PageHeading({ eyebrow, title, description, children }) { return <div className="page-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description && <p>{description}</p>}</div><div className="heading-actions">{children}</div></div>; }
function focusableElements(container) {
  return Array.from(container?.querySelectorAll('a[href], button:not(:disabled), input:not(:disabled), textarea:not(:disabled), select:not(:disabled), [tabindex]:not([tabindex="-1"])') || []).filter(node => node.getClientRects().length && !node.closest('[inert]'));
}
function trapFocus(event, container) {
  if (event.key !== 'Tab') return;
  const nodes = focusableElements(container);
  if (!nodes.length) { event.preventDefault(); container?.focus(); return; }
  const first = nodes[0], last = nodes[nodes.length - 1];
  if (!nodes.includes(document.activeElement)) { event.preventDefault(); (event.shiftKey ? last : first).focus(); }
  else if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
}
function Modal({ title, subtitle, children, onClose, wide = false }) {
  const ref = useRef();
  useEffect(() => {
    const previous = document.activeElement;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    (focusableElements(ref.current)[0] || ref.current)?.focus();
    const listener = event => {
      const dialogs = document.querySelectorAll('[role="dialog"]');
      if (dialogs[dialogs.length - 1] !== ref.current) return;
      if (event.key === 'Escape') { event.preventDefault(); onClose(); }
      trapFocus(event, ref.current);
    };
    document.addEventListener('keydown', listener);
    return () => { document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', listener); if (previous?.isConnected) previous.focus({ preventScroll: true }); };
  }, []);
  return <div className="modal-overlay" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section ref={ref} tabIndex={-1} className={`modal ${wide ? 'wide-modal' : ''}`} role="dialog" aria-modal="true" aria-label={title}><header className="modal-header"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button type="button" className="icon-button" onClick={onClose} aria-label="关闭"><X size={20} /></button></header>{children}</section></div>;
}
function EvidenceButtons({ ids = [], records }) { const { setEvidence } = useApp(); const references = ids.length ? ids : records?.map(record => record.id) || []; return references.length ? <div className="evidence-buttons">{references.map((id, index) => <button type="button" data-testid="evidence-link" key={id} onClick={() => setEvidence(records?.find(record => record.id === id) || id)}><Link2 size={12} />证据{references.length > 1 ? ` ${index + 1}` : ''}</button>)}</div> : <span className="evidence-missing">暂无证据</span>; }
function EntityMark({ entity, small }) { const name = entity.name || '?'; return <span className={`entity-mark ${small ? 'small' : ''} mark-${name.charCodeAt(0) % 6}`} aria-hidden="true">{name.slice(0, name.length > 8 ? 1 : 2).toUpperCase()}</span>; }

function App() {
  const [route, setRoute] = useState(location.hash.slice(1) || 'discover');
  const [session, setSession] = useState({ user: null, mode: null });
  const [revision, setRevision] = useState(0);
  const [toast, setToast] = useState(null);
  const [login, setLogin] = useState(false);
  const [evidence, setEvidence] = useState(null);
  const [drawer, setDrawer] = useState(false);
  const [search, setSearch] = useState('');
  const sidebarRef = useRef();
  const menuRef = useRef();
  const mainRef = useRef();
  const refresh = () => setRevision(value => value + 1);
  const notify = (message, error = false) => setToast({ message, error, key: Date.now() });
  useEffect(() => { let active = true; api('/session').then(data => { if (active) { setSession(data); setCsrf(data.csrf_token); } }).catch(() => {}); return () => { active = false; }; }, [revision]);
  useEffect(() => { const handle = () => { setRoute(location.hash.slice(1) || 'discover'); setDrawer(false); window.scrollTo(0, 0); requestAnimationFrame(() => mainRef.current?.focus({ preventScroll: true })); }; window.addEventListener('hashchange', handle); return () => window.removeEventListener('hashchange', handle); }, []);
  useEffect(() => {
    if (!drawer || !window.matchMedia('(max-width: 760px)').matches) return;
    const previous = document.activeElement;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const frame = requestAnimationFrame(() => (sidebarRef.current?.querySelector('[aria-current="page"]') || focusableElements(sidebarRef.current)[0])?.focus());
    const onKey = event => { if (event.key === 'Escape') { event.preventDefault(); setDrawer(false); } trapFocus(event, sidebarRef.current); };
    const onResize = () => { if (!window.matchMedia('(max-width: 760px)').matches) setDrawer(false); };
    document.addEventListener('keydown', onKey);
    window.addEventListener('resize', onResize);
    return () => { cancelAnimationFrame(frame); document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', onKey); window.removeEventListener('resize', onResize); if (previous?.isConnected) previous.focus({ preventScroll: true }); };
  }, [drawer]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(null), 4500); return () => clearTimeout(timer); }, [toast]);
  const mutate = async (path, method = 'POST', body, message) => { try { const result = await api(path, { method, body }); if (result.csrf_token) setCsrf(result.csrf_token); if (path === '/auth/demo' && result.user) setSession(previous => ({ ...previous, ...result })); if (path === '/auth/logout' || path === '/account' && method === 'DELETE') { setSession(previous => ({ ...previous, user: null })); setCsrf(''); } const created = item(result); if (path === '/research-tasks' && method === 'POST') track('task_created', { task_id: created?.id }); if (/\/research-tasks\/[^/]+\/candidates$/.test(path) && method === 'POST') track('candidate_added', { task_id: path.split('/')[2], entity_id: body?.entity_id }); if (path === '/watches' && method === 'POST') track('watch_created', { entity_id: body?.entity_id }); if (path === '/notes' && method === 'POST') track('note_created', { entity_id: body?.entity_id, task_id: body?.task_id }); if (/\/research-tasks\/[^/]+$/.test(path) && method === 'PATCH' && body?.status) track('decision_updated', { task_id: path.split('/')[2] }); if (path === '/corrections' && method === 'POST') track('correction_submitted', { entity_id: body?.entity_id }); refresh(); if (message) notify(message); return result; } catch (error) { if (error.status === 401) setLogin(true); notify(error.message, true); throw error; } };
  const value = { session, revision, refresh, notify, mutate, setLogin, setEvidence };
  const section = route.split(/[/?]/)[0];
  const routeIdentifier = route.split('?')[0].split('/')[1];
  const invalidRoute = ['entity', 'research', 'digests'].includes(section) && ((section === 'entity' && routeIdentifier === undefined) || routeIdentifier !== undefined && (!routeIdentifier || decodeRouteSegment(routeIdentifier) === null));
  useEffect(() => { if (invalidRoute) return; if (section === 'discover') track('feed_view', {}, true); if (section === 'entity') track('entity_view', { entity_id: decodeRouteSegment(route.split('/')[1] || '') }, true); if (section === 'research' && route.includes('/')) track('comparison_view', { task_id: decodeRouteSegment(route.split('/')[1] || '') }, true); }, [route]);
  const routeTitle = navItems.find(nav => nav.path === section)?.label || ({ entity: '项目档案', admin: '运营后台', method: '来源与方法', settings: '账户设置' }[section]) || '发现';
  return <AppContext.Provider value={value}><div className="app-shell"><a className="skip-link" href="#main-content" onClick={event => { event.preventDefault(); mainRef.current?.focus(); }}>跳到页面内容</a>
    {drawer && <div className="sidebar-scrim" onClick={() => setDrawer(false)} />}
    <aside ref={sidebarRef} id="workspace-navigation" className={`sidebar ${drawer ? 'open' : ''}`} role={drawer ? 'dialog' : undefined} aria-modal={drawer ? true : undefined} aria-label="工作台导航">{drawer && <button type="button" className="icon-button drawer-close" onClick={() => setDrawer(false)} aria-label="关闭导航"><X size={20} /></button>}
      <a className="brand" href="#discover"><span className="brand-icon"><Radar size={25} strokeWidth={1.7} /></span><span>开源产品雷达<small>OPEN PRODUCT RADAR</small></span></a>
      <div className="workspace-label"><span className="workspace-dot" />研究工作台<Badge>Beta</Badge></div>
      <nav className="main-nav" aria-label="主导航">{navItems.map(({ path, label, icon: Icon }) => <a key={path} href={`#${path}`} className={section === path ? 'active' : ''} aria-current={section === path ? 'page' : undefined}><Icon size={18} strokeWidth={1.7} /><span>{label}</span>{['research', 'watches'].includes(path) && <PersonalCount path={path} />}{section === path && <span className="nav-active-dot" />}</a>)}</nav>
      <div className="sidebar-note"><span className="tiny-label">从发现，到判断</span><p>让每一次技术选择，<br />都有迹可循。</p><div className="orbital"><span /><span /><Radar size={65} strokeWidth={0.7} /></div></div>
      <div className="sidebar-bottom">{session.user && ['admin', 'editor'].includes(session.user.role) && <a href="#admin" className={section === 'admin' ? 'active' : ''}><Settings2 size={17} />运营后台</a>}<a href="#method"><BookOpen size={17} />来源与方法<ArrowUpRight size={13} /></a><a href="#settings"><CircleHelp size={17} />账户与偏好</a><div className="sidebar-footnote"><span className={`status-dot ${session.mode === 'demo' ? 'demo-dot' : ''}`} />{session.mode === 'demo' ? '独立演示数据环境' : session.mode ? '研究信息工作台' : '正在连接数据服务'}</div></div>
    </aside>
    <div className="main-shell" inert={drawer ? true : undefined}><header className="topbar"><div className="breadcrumb"><button ref={menuRef} className="icon-button mobile-menu" aria-label="打开导航" aria-expanded={drawer} aria-controls="workspace-navigation" onClick={() => setDrawer(true)}><Menu size={20} /></button><span>工作台</span><ChevronRight size={13} /><strong>{routeTitle}</strong></div><div className="topbar-actions"><form className="global-search" onSubmit={event => { event.preventDefault(); navigate(`entities?q=${encodeURIComponent(search)}`); }}><Search size={15} /><input aria-label="搜索项目与产品" value={search} onChange={event => setSearch(event.target.value)} placeholder="搜索项目、产品…" /><kbd>↵</kbd></form><a href="#watches" className="icon-button notification-button" aria-label="查看跟踪更新"><Bell size={18} /></a><span className="topbar-divider" />{session.user ? <a className="user-menu" href="#settings"><span className="avatar">{session.user.name?.[0] || '研'}</span><span>{session.user.name || '研究员'}</span></a> : <Button variant="dark" onClick={() => setLogin(true)}>{session.mode === 'production' && !loginPresentation(session).available ? '登录说明' : '登录工作区'}<ArrowUpRight size={14} /></Button>}</div></header>
      <main ref={mainRef} id="main-content" className="main-content" tabIndex={-1}>{invalidRoute ? <InvalidRoute /> : section === 'discover' ? <Discover /> : section === 'entities' ? <EntityDirectory route={route} /> : section === 'entity' ? <EntityDetail id={decodeRouteSegment(route.split('/')[1] || '')} /> : section === 'research' ? <Research route={route} /> : section === 'watches' ? <Watches /> : section === 'digests' ? <Digests route={route} /> : section === 'admin' ? <Admin /> : section === 'settings' ? <Settings /> : <Method />}</main>
      <footer className="page-footer"><span>开源产品雷达<span className="footer-dot">·</span>为具体任务，寻找可靠依据。</span><a href="#method">数据边界与研究方法<ArrowUpRight size={12} /></a></footer>
    </div>
    {toast && <div key={toast.key} className={`toast ${toast.error ? 'error' : ''}`} role="status">{toast.error ? <AlertTriangle size={17} /> : <Check size={17} />}{toast.message}<button onClick={() => setToast(null)} aria-label="关闭提示"><X size={15} /></button></div>}
    {login && <Login onClose={() => setLogin(false)} />}{evidence && <EvidencePanel id={typeof evidence === 'string' ? evidence : evidence.id} record={typeof evidence === 'object' ? evidence : null} onClose={() => setEvidence(null)} />}
  </div></AppContext.Provider>;
}

function InvalidRoute() { return <Empty icon={AlertTriangle} title="这个页面链接无效" description="链接中的项目标识无法识别。请从项目目录重新选择，公开资料仍可正常浏览。" action={<a className="button primary" href="#entities">返回项目与产品<ArrowRight size={15} /></a>} />; }

function PersonalCount({ path }) {
  const { session } = useApp();
  const state = useData(session.user ? (path === 'research' ? '/research-tasks' : '/watches') : null);
  const count = list(state.data).length;
  return count ? <span className="nav-count">{count}</span> : null;
}

function Login({ onClose }) {
  const { session, mutate, refresh } = useApp();
  const [busy, setBusy] = useState(false);
  const auth = loginPresentation(session);
  return <Modal title={auth.available ? '把发现，变成你的研究' : '公开资料可浏览，登录尚未开放'} subtitle={auth.available ? '保存候选、关注变化，让下一次判断从这里继续。' : '当前无需登录即可查看已采集的项目和原始出处。'} onClose={onClose}><div className="login-body"><div className="login-symbol"><Radar size={42} strokeWidth={1.3} /></div>
    {auth.available ? <p>你的研究任务、关注原因和笔记默认仅自己可见。<br />登录不代表订阅邮件，通知由你单独选择。</p> : <div className="notice"><Info size={16} /><span>{auth.reason}</span></div>}
    {auth.demo ? <><div className="notice"><Info size={16} /><span>当前为演示环境。系统会创建独立演示账户，内容为明确标识的演示样本，可实际保存和管理研究记录。</span></div><Button data-testid="demo-login" variant="primary" busy={busy} onClick={async () => { setBusy(true); try { await mutate('/auth/demo', 'POST', {}, '已进入独立演示工作区'); onClose(); } catch {} finally { setBusy(false); } }}>进入演示工作区<ArrowRight size={16} /></Button></> : auth.github ? <a className="button dark" href="/api/v1/auth/github"><Github size={17} />使用 GitHub 登录</a> : <><Button variant="primary" onClick={() => { onClose(); navigate('discover'); }}>继续浏览公开资料<ArrowRight size={16} /></Button><button className="text-button login-recheck" onClick={refresh}>重新检查登录是否开放</button></>}
  </div></Modal>;
}

function GrowthExplanation({ entities, period = '24h', collection }) {
  const repositories = entities.filter(entity => entity.kind === 'repository');
  if (!repositories.length || repositories.every(entity => trendPresentation(entity, period).comparable)) return null;
  return <aside className="growth-explanation" aria-label="Star 总量与增长说明"><Info size={17} /><div><h3>Star 总量已知，不代表最近增长已知</h3><p>当前 Stars 是采集当时的累计数。最近 {period === '7d' ? '7 天' : '24 小时'} 的净变化，还需要约 {period === '7d' ? '7 天' : '24 小时'} 前的一份有效记录。缺少对照的项目显示“待对比”，不代表零增长或采集失败。</p><p className="growth-schedule">{scheduleExplanation(collection)}</p></div></aside>;
}

function EntityGrowth({ entity }) {
  if (entity.kind !== 'repository') return null;
  return <section className="panel content-panel entity-growth"><div className="panel-title-row"><h2>当前总量与最近增长</h2><span>当前 Stars：{number(entity.stars)}</span></div><div className="entity-growth-periods">{['24h', '7d'].map(period => { const trend = trendPresentation(entity, period); return <div key={period}><h3>最近 {trend.windowName}<span className={trend.comparable ? trend.value < 0 ? 'negative' : 'positive' : 'growth-pending'}>{trend.comparable ? `${trend.value > 0 ? '+' : ''}${number(trend.value)}` : trend.label}</span></h3><p>{trend.description}</p></div>; })}</div><p className="growth-schedule">{scheduleExplanation(entity.collection)}</p></section>;
}

function CollectionStatus({ collection }) {
  if (!collection || typeof collection !== 'object') return null;
  const sources = Array.isArray(collection.sources) && collection.sources.length
    ? collection.sources
    : [{ name: '本次采集', counts: collection.counts, summary: collection.summary }];
  return <section className="collection-status-panel" aria-label="采集状态">
    <div className="collection-status-heading"><h2><RefreshCw size={15} />采集状态</h2><span>执行结果与持续更新分别展示</span></div>
    {sources.map((source, index) => {
      const counts = source.counts || {};
      const failed = typeof counts.failed === 'number' && counts.failed > 0;
      const succeeded = typeof counts.success === 'number' && counts.success > 0;
      const tone = failed ? 'attention' : succeeded ? 'success' : 'neutral';
      const Icon = failed ? AlertTriangle : succeeded ? CheckCheck : Info;
      const label = failed ? (succeeded ? '部分采集成功' : '采集未完成') : succeeded ? '已取得真实数据' : source.source_status === 'paused' ? '来源已暂停' : counts.pending > 0 ? '等待执行' : counts.running > 0 ? '有执行中任务' : '暂无已完成记录';
      const fallback = [['success', '个成功'], ['failed', '个失败'], ['pending', '个待执行'], ['running', '个执行中']]
        .filter(([key]) => typeof counts[key] === 'number' && counts[key] > 0)
        .map(([key, caption]) => `${number(counts[key])} ${caption}`).join('，');
      const splitSummary = !!source.result_summary;
      return <article className="collection-source-card" key={source.source_id || index}>
        <div className={`collection-result ${tone}`}><Icon size={19} /><div className="collection-result-copy"><div className="collection-source-title"><strong>{source.name || '采集来源'}</strong><Badge tone={failed ? 'amber' : succeeded ? 'green' : 'neutral'}>{label}</Badge></div><p>{source.result_summary || source.summary || fallback || '暂未提供采集执行结果。'}</p></div></div>
        {((splitSummary && (source.schedule_summary || source.retention_summary)) || source.last_attempt_at || source.last_success_at) && <div className="collection-continuity">
          {splitSummary && source.schedule_summary && <p><span>持续更新</span>{source.schedule_summary}</p>}
          {splitSummary && source.retention_summary && <p><span>已有数据</span>{source.retention_summary}</p>}
          {(source.last_attempt_at || source.last_success_at) && <div className="collection-times">{source.last_attempt_at && <span>最近执行：{datetime(source.last_attempt_at)}</span>}{source.last_success_at && <span>最近成功：{datetime(source.last_success_at)}</span>}</div>}
        </div>}
      </article>;
    })}
  </section>;
}

function Discover() {
  const { session, setLogin } = useApp();
  const [period, setPeriod] = useState('24h'); const [topic, setTopic] = useState(''); const [language, setLanguage] = useState(''); const [kind, setKind] = useState('repository');
  const query = new URLSearchParams({ period, topic, language, kind }).toString(); const state = useData(`/feed?${query}`); const productFeed = useData(`/feed?kind=product&period=${period}`); const all = useData('/entities');
  const feed = state.data || {}; const entities = list(feed); const allEntities = list(all.data); const events = productFeed.data?.events || [];
  const showCollection = (feed.mode || session.mode) === 'production' && !!feed.collection;
  const collectionWarnings = new Set(showCollection ? (feed.collection.warnings || []).map(warning => typeof warning === 'string' ? warning : warning.message) : []);
  const warnings = (feed.warnings || []).map(warning => typeof warning === 'string' ? warning : warning.message).filter(message => message && !collectionWarnings.has(message));
  const topics = [...new Set(allEntities.map(entity => entity.topic).filter(Boolean))]; const languages = [...new Set(allEntities.map(entity => entity.language).filter(Boolean))];
  const currentDate = feed.as_of ? new Date(feed.as_of) : new Date();
  const stats = [{ label: '收录开源项目', value: feed.stats?.repositories, icon: Github, caption: '已保存的仓库资料', tone: 'indigo' }, { label: '关联产品', value: feed.stats?.products, icon: Layers3, caption: '独立建档 · 循证关联', tone: 'blue' }, { label: '已收录变化', value: feed.stats?.events, icon: CircleDot, caption: '版本、能力与条件变化', tone: 'green' }, { label: '研究来源', value: feed.stats?.sources, icon: Link2, caption: '原始出处可追溯', tone: 'amber' }];
  return <><div className="discovery-heading"><div className="eyebrow"><span className="tiny-line" />YOUR NEXT DISCOVERY<span className="eyebrow-date">{currentDate.toLocaleDateString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit' })}</span></div><div className="hero-title-row"><div><h1>发现值得研究的下一步<span>。</span></h1><p>从开源趋势到产品变化，在证据中找到适合你的选择。</p></div><Button onClick={() => session.user ? navigate('research?new=1') : setLogin(true)}><Plus size={16} />新建研究任务</Button></div><div className="coverage-line"><span className="status-dot" />本平台跟踪样本<span className="separator">/</span>业务自动化研究方向<span className="separator">/</span>{feed.mode === 'demo' || session.mode === 'demo' ? <span className="demo-label"><Info size={12} />演示数据 · 非实时榜单</span> : <span>截至 {datetime(feed.as_of)}</span>}</div></div>
    <div className="stats-grid">{stats.map(({ label, value, icon: Icon, caption, tone }) => <div className="stat-card" key={label}><div className="stat-label">{label}<span className={`stat-icon ${tone}`}><Icon size={17} strokeWidth={1.6} /></span></div><div className="stat-value">{number(value)}<span>{label === '研究来源' ? '个来源' : '个'}</span></div><div className="stat-caption">{caption}</div></div>)}</div>
    {showCollection && <CollectionStatus collection={feed.collection} />}
    {!!warnings.length && <div className="notice warning"><AlertTriangle size={16} /><span>{warnings.join('；')}</span></div>}
    <div className="discovery-columns"><section className="panel trends-panel"><div className="panel-heading"><div className="section-title"><span className="section-icon"><Compass size={17} /></span><h2>值得关注的发现</h2><Badge>跟踪样本</Badge></div><div className="segment" aria-label="时间范围"><button aria-pressed={period === '24h'} onClick={() => setPeriod('24h')} className={period === '24h' ? 'selected' : ''}>24 小时</button><button aria-pressed={period === '7d'} onClick={() => setPeriod('7d')} className={period === '7d' ? 'selected' : ''}>7 天</button></div></div><div className="discovery-tabs"><button aria-pressed={kind === 'repository'} className={kind === 'repository' ? 'active' : ''} onClick={() => setKind('repository')}><Github size={15} />开源项目</button><button aria-pressed={kind === 'product'} className={kind === 'product' ? 'active' : ''} onClick={() => setKind('product')}><Layers3 size={15} />产品动态</button><span className="results-count">{entities.length} 个结果</span></div><div className="filter-row"><div className="select-wrap"><Filter size={13} /><select aria-label="筛选研究方向" value={topic} onChange={e => setTopic(e.target.value)}><option value="">全部方向</option>{topics.map(value => <option key={value}>{value}</option>)}</select></div><div className="select-wrap"><span className="language-dot" /><select aria-label="筛选编程语言" value={language} onChange={e => setLanguage(e.target.value)}><option value="">全部语言</option>{languages.map(value => <option key={value}>{value}</option>)}</select></div><span className="sort-caption"><SlidersHorizontal size={13} />{sortingPresentation(feed.sort, entities, period, kind)}</span></div><DataState state={state}>{kind === 'repository' && <GrowthExplanation entities={entities} period={period} collection={feed.collection} />}<RepositoryTable entities={entities} period={period} kind={kind} contentStatus={feed.content_status} /></DataState><div className="table-foot"><span><Info size={12} />Star 反映关注，不代表用户量或产品质量</span><a href="#entities">浏览全部<ArrowRight size={13} /></a></div></section>
    <aside className="right-rail"><section className="research-prompt"><div className="eyebrow"><span className="research-dot" />把浏览变成研究</div><h2>先有问题，<br />再找合适的方案。</h2><p>写下你的场景与约束，围绕证据比较 2—5 个候选。</p><div className="research-steps"><span>明确需求</span><ChevronRight size={12} /><span>比较依据</span><ChevronRight size={12} /><span>持续跟踪</span></div><Button variant="primary" onClick={() => session.user ? navigate('research?new=1') : setLogin(true)}>开始我的研究<ArrowRight size={15} /></Button><div className="prompt-decoration"><PanelsTopLeft size={96} strokeWidth={0.6} /></div></section><section className="panel events-panel"><div className="panel-heading"><h2>近期产品变化</h2><span className="live-dot" /></div><div className="event-timeline"><DataState state={productFeed}>{events.slice(0, 4).map(event => <EventCard key={event.id} event={event} compact />)}{!events.length && <ProductEventsEmpty content={productFeed.data?.content_status || feed.content_status} />}</DataState></div><a className="rail-link" href="#entities?kind=product">查看产品档案<ArrowRight size={13} /></a></section><div className="method-note"><ShieldCheck size={20} strokeWidth={1.4} /><div><strong>结论有出处，未知有边界</strong><p>每一条重要判断，都可以回到原始证据。</p><a href="#method">了解我们的研究方法<ArrowUpRight size={12} /></a></div></div></aside></div>
    <section className="bottom-banner"><span className="banner-icon"><Telescope size={25} strokeWidth={1.3} /></span><div><h3>值得关注的，不只有今天的热度。</h3><p>记住当初为什么关注，下一次变化才真正与你有关。</p></div><a href="#watches">建立持续跟踪<ArrowRight size={15} /></a></section>
  </>;
}

function RepositoryTable({ entities, period = '24h', contentStatus, kind }) {
  const { session, setLogin } = useApp();
  const [watchEntity, setWatchEntity] = useState(null);
  if (!entities.length) {
    if (kind === 'product') { const empty = productEmptyPresentation(contentStatus); return <Empty title={empty.title} description={`${empty.description} ${empty.nextStep}`} action={<a className="button secondary" href="#entities?kind=repository">查看已收录仓库<ArrowRight size={15} /></a>} />; }
    return <Empty title="这个范围还没有收录内容" description="试试其他筛选条件。未收录不代表项目没有变化。" />;
  }
  return <><div className="repository-table"><div className="repo-table-head"><span>项目 / 产品</span><span>当前 Stars</span><span>{period === '7d' ? '7 天净变化' : '24h 净变化'}</span><span /></div>{entities.map(entity => {
    const trend = trendPresentation(entity, period);
    return <div className="repo-row" key={entity.id}><div className="repo-primary"><EntityMark entity={entity} /><div className="repo-copy"><a className="repo-name" href={`#entity/${encodeURIComponent(entity.id)}`}>{entity.name}<ArrowUpRight size={13} />{entity.featured && <span className="featured-dot" title="编辑精选" />}</a><p>{entity.description || '暂无描述'}</p><div className="repo-meta">{entity.language && <span><i className={`lang-dot ${entity.language.toLowerCase()}`} />{entity.language}</span>}{entity.topic && <span className="topic-pill">{entity.topic}</span>}{entity.featured && <span className="editor-label">编辑精选</span>}{entity.kind === 'repository' && <span className="mobile-star-total">当前 Stars {shortNumber(entity.stars)}</span>}</div></div></div><div className="star-value">{entity.kind === 'repository' ? <><Star size={12} />{shortNumber(entity.stars)}</> : <Badge>产品</Badge>}</div><div className="delta-value">{entity.kind !== 'repository' ? <span className="muted">—</span> : trend.comparable ? <span className={trend.value >= 0 ? 'positive' : 'negative'}>{trend.value > 0 ? '+' : ''}{number(trend.value)}</span> : <span className="history-missing" aria-label={`${entity.name}：${trend.description}`}><strong>{trend.label}</strong><small>{trend.reason}</small></span>}</div><button className="follow-button" title={`跟踪 ${entity.name}`} aria-label={`跟踪 ${entity.name}`} onClick={() => session.user ? setWatchEntity(entity) : setLogin(true)}><Plus size={17} /></button></div>;
  })}</div>{watchEntity && <WatchForm entity={watchEntity} onClose={() => setWatchEntity(null)} />}</>;
}

function ProductEventsEmpty({ content }) { const empty = productEmptyPresentation(content, true); return <div className="rail-empty product-events-empty"><strong>{empty.title}</strong><p>{empty.description}</p><p>{empty.nextStep}</p><a href="#entities?kind=repository">查看已收录仓库<ArrowRight size={13} /></a></div>; }

function EventCard({ event, compact }) { return <article className={`event-card ${compact ? 'compact' : ''}`}><div className="event-top"><span className={`event-type event-${event.type}`}>{EVENT_TYPES[event.type] || event.type || '变化'}</span><time>{date(event.published_at || event.observed_at)}</time></div><a className="event-title" href={`#entity/${encodeURIComponent(event.entity_id)}`}>{event.title}</a>{!compact && <p>{event.summary}</p>}<div className="event-bottom"><span>{event.entity_name || '项目变化'}{event.is_demo ? ' · 演示' : ''}</span><EvidenceButtons ids={event.evidence_ids} records={event.evidence} /></div></article>; }

function EntityDirectory({ route }) {
  const initial = new URLSearchParams(route.split('?')[1] || ''); const [q, setQ] = useState(initial.get('q') || ''); const [kind, setKind] = useState(initial.get('kind') || ''); const [search, setSearch] = useState(q);
  useEffect(() => { const next = new URLSearchParams(route.split('?')[1] || ''); setQ(next.get('q') || ''); setSearch(next.get('q') || ''); setKind(next.get('kind') || ''); }, [route]);
  const state = useData(`/entities?${new URLSearchParams({ q, kind })}`);
  const contextState = useData('/feed?kind=product&limit=1');
  const entities = list(state.data).filter(entity => !kind || entity.kind === kind);
  return <><PageHeading eyebrow="EXPLORE THE LANDSCAPE" title="项目与产品" description="理解一个项目，先从它的能力、条件和原始出处开始。" /><section className="panel"><div className="directory-toolbar"><div className="segment"><button aria-pressed={!kind} className={!kind ? 'selected' : ''} onClick={() => setKind('')}>全部对象</button><button aria-pressed={kind === 'repository'} className={kind === 'repository' ? 'selected' : ''} onClick={() => setKind('repository')}>开源项目</button><button aria-pressed={kind === 'product'} className={kind === 'product' ? 'selected' : ''} onClick={() => setKind('product')}>产品</button></div><form className="search-field" onSubmit={e => { e.preventDefault(); setQ(search); }}><Search size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="按名称、描述搜索" aria-label="目录搜索" /><button aria-label="执行搜索"><ArrowRight size={15} /></button></form></div><DataState state={state}><GrowthExplanation entities={entities} collection={contextState.data?.collection} /><RepositoryTable entities={entities} kind={kind} contentStatus={contextState.data?.content_status} /></DataState><div className="table-foot"><span>当前显示 {entities.length} 个对象 · 本平台跟踪样本</span><a href="#method">覆盖说明<ArrowUpRight size={12} /></a></div></section></>;
}

function EntityDetail({ id }) {
  const state = useData(`/entities/${encodeURIComponent(id)}`); const { session, setLogin } = useApp(); const [watch, setWatch] = useState(false); const [candidate, setCandidate] = useState(false); const [correction, setCorrection] = useState(false); const entity = item(state.data);
  return <DataState state={state}>{entity && <><a className="back-link" href="#entities">← 返回项目与产品</a><div className="entity-header"><EntityMark entity={entity} /><div><div className="inline-badges"><Badge>{entity.kind === 'product' ? '产品' : '开源项目'}</Badge>{entity.is_demo && <Badge tone="amber">演示样本</Badge>}{entity.featured && <Badge tone="indigo">编辑精选</Badge>}</div><h1>{entity.name}</h1><p>{entity.description || '暂无信息'}</p></div><div className="entity-actions"><Button variant="primary" onClick={() => session.user ? setWatch(true) : setLogin(true)}><Plus size={16} />持续跟踪</Button><Button onClick={() => session.user ? setCandidate(true) : setLogin(true)}><PanelsTopLeft size={15} />加入研究</Button></div></div><div className="entity-links"><External href={entity.repository_url}><Github size={14} />代码仓库</External><External href={entity.website}>官方网站</External><External href={entity.docs_url}>使用文档</External><span>观察时间 {datetime(entity.observed_at)}</span></div>
    <div className="detail-layout"><div className="detail-main"><EntityGrowth entity={entity} /><section className="panel content-panel"><h2>能力与适用边界</h2><p className="section-description">结论仅适用于注明的版本、套餐与部署方式。</p>{entity.assertions?.length ? <div className="assertion-list">{entity.assertions.map(assertion => <div className="assertion-row" key={assertion.id}><div><span className={`support-status ${assertion.status}`}><CircleDot size={13} />{SUPPORT[assertion.status] || '待核实'}</span><h3>{assertion.label || assertion.dimension}</h3></div><div><p>{assertion.value || '暂无信息'}</p><small>{assertion.scope || '适用范围待核实'}</small><EvidenceButtons ids={assertion.evidence_ids} /></div></div>)}</div> : <Empty title="能力信息有待核查" description="尚无足够证据，不据此推断支持或不支持。" />}</section><section className="panel content-panel"><h2>版本、套餐与部署</h2>{entity.editions?.length ? <div className="edition-grid">{entity.editions.map(edition => <div className="edition-card" key={edition.id}><h3>{edition.name}</h3><Badge>{edition.deployment || '部署方式待核实'}</Badge><dl><dt>价格条件</dt><dd>{edition.price != null ? `${edition.currency || ''} ${edition.price}${edition.billing_period ? ` / ${edition.billing_period}` : ''}` : '暂无信息'}</dd><dt>适用版本</dt><dd>{edition.version || '暂无信息'}</dd></dl><EvidenceButtons ids={edition.evidence_ids} /></div>)}</div> : <p className="muted">暂无经过核查的版本信息。</p>}</section><section className="panel content-panel"><h2>近期变化</h2>{entity.events?.length ? entity.events.map(event => <EventCard key={event.id} event={event} />) : <div className="entity-event-empty"><p className="muted">{entity.content_status?.pending_release_events > 0 ? `已取得 ${number(entity.content_status.pending_release_events)} 条版本记录，尚待审核。审核通过前不会作为已发布变化展示。` : '暂无已发布事件。这只说明尚无已核查并发布的内容，不代表项目没有更新。'}</p><External href={entity.repository_url || entity.website}>查看原始发布来源</External></div>}</section><Notes entityId={entity.id} /></div><aside className="detail-aside"><section className="panel content-panel"><h2>项目资料</h2><dl className="facts"><dt>所属方向</dt><dd>{entity.topic || '暂无信息'}</dd><dt>主要语言</dt><dd>{entity.language || '暂无信息'}</dd><dt>许可证</dt><dd>{entity.license || '暂无信息'}</dd><dt>当前 Stars</dt><dd>{number(entity.stars)}</dd><dt>增长记录</dt><dd>{trendPresentation(entity, '24h').comparable ? '可计算24小时净变化' : trendPresentation(entity, '24h').reason}</dd><dt>24h 观察跨度</dt><dd>{entity.trend_24h?.interval_hours != null ? `${Number(entity.trend_24h.interval_hours).toFixed(1)} 小时` : '暂无可比区间'}</dd><dt>7天观察跨度</dt><dd>{entity.trend_7d?.interval_hours != null ? `${Number(entity.trend_7d.interval_hours).toFixed(1)} 小时` : '暂无可比区间'}</dd><dt>首次收录</dt><dd>{date(entity.first_seen_at)}</dd><dt>创建时间</dt><dd>{date(entity.created_at)}</dd></dl>{entity.original_description && <div className="original-description"><span className="tiny-label">原始描述</span><p>{entity.original_description}</p></div>}</section><section className="panel content-panel"><h2>相关项目与产品</h2>{entity.relations?.length ? entity.relations.map((relation, index) => <div className="relation" key={relation.id || index}><strong>{relation.related_entity_id ? <a href={`#entity/${encodeURIComponent(relation.related_entity_id)}`}>{relation.related_name || relation.target_name || relation.name}<ArrowUpRight size={12} /></a> : relation.related_name || relation.target_name || relation.entity_name || relation.name || relation.target_entity_id || '关联对象'}</strong><p>{relation.type || relation.relation_type} · {({ confirmed: '已确认', rejected: '已否定', needs_review: '待复核', candidate: '候选关系' })[relation.status] || relation.status || '待核查'}</p><EvidenceButtons ids={relation.evidence_ids} /></div>) : <p className="muted">暂无已确认的关联。</p>}</section><div className="correction-prompt"><ShieldCheck size={18} /><p>发现遗漏或不准确？<br />提供出处，帮助改进研究。</p><button className="text-button" onClick={() => session.user ? setCorrection(true) : setLogin(true)}>提交纠错<ArrowRight size={13} /></button></div></aside></div>{watch && <WatchForm entity={entity} onClose={() => setWatch(false)} />}{candidate && <AddCandidate entity={entity} onClose={() => setCandidate(false)} />}{correction && <CorrectionForm entityId={entity.id} onClose={() => setCorrection(false)} />}</>}</DataState>;
}

function EvidencePanel({ id, record, onClose }) {
  const state = useData(record ? null : `/evidence/${encodeURIComponent(id)}`); const evidence = record || item(state.data); useEffect(() => { if (evidence?.id) track('evidence_view', { entity_id: evidence.entity_id }, true); }, [evidence?.id]); const { session, setLogin } = useApp(); const [correction, setCorrection] = useState(false);
  return <Modal title="回到原始证据" subtitle="区分出处、观察时间与人工核查时间。" onClose={onClose}><div className="evidence-panel"><DataState state={state}>{evidence && <><div className="inline-badges"><Badge tone="indigo">{evidence.source_name || '原始来源'}</Badge>{evidence.is_demo && <Badge tone="amber">演示证据</Badge>}<Badge>{({ approved: '已审核', published: '已发布', reviewed: '已核查', pending: '待审核', retracted: '已撤回' })[evidence.review_status] || evidence.review_status || '待核查'}</Badge></div><h3>{evidence.title}</h3><blockquote>{evidence.excerpt || '暂无可展示的引用文本，请查看原始出处。'}</blockquote><External className="source-link" href={evidence.url}>打开原始出处</External><dl className="facts"><dt>源发布时间</dt><dd>{datetime(evidence.published_at)}</dd><dt>采集时间</dt><dd>{datetime(evidence.fetched_at)}</dd><dt>人工核查</dt><dd>{datetime(evidence.reviewed_at)}</dd><dt>使用权限</dt><dd>{evidence.permission_status || '待核实'}</dd></dl>{evidence.is_demo && <div className="notice"><Info size={15} /><span>此记录用于演示证据链，不能作为对当前产品能力的实时确认。</span></div>}<Button onClick={() => session.user ? setCorrection(true) : setLogin(true)}>这条证据有问题 · 提交纠错</Button></>}</DataState></div>{correction && <CorrectionForm evidenceId={id} onClose={() => setCorrection(false)} />}</Modal>;
}

function CorrectionForm({ entityId, evidenceId, onClose }) { const { mutate } = useApp(); const [busy, setBusy] = useState(false); return <Modal title="提交资料纠错" subtitle="提交后进入人工审核，不会直接更改公开内容。" onClose={onClose}><form className="form-body" onSubmit={async e => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); setBusy(true); try { await mutate('/corrections', 'POST', { ...data, entity_id: entityId, evidence_id: evidenceId }, '纠错已提交，等待审核'); onClose(); } catch {} finally { setBusy(false); } }}><Field label="需要修正的内容"><textarea name="description" required minLength={5} rows={5} placeholder="请说明问题、适用版本或新的证据…" /></Field><Field label="参考出处（选填）"><input name="url" type="url" placeholder="https://…" /></Field><div className="form-actions"><Button onClick={onClose} type="button">取消</Button><Button busy={busy} variant="primary" type="submit">提交审核<Send size={14} /></Button></div></form></Modal>; }

function Research({ route }) {
  const { session, setLogin, mutate } = useApp(); const taskId = route.split('?')[0].split('/')[1]; const state = useData(session.user ? '/research-tasks' : null); const [editing, setEditing] = useState(null); const [creating, setCreating] = useState(false);
  useEffect(() => { if (route.includes('new=1')) { if (session.user) setCreating(true); else setLogin(true); } }, [route, session.user]);
  if (!session.user) return <><PageHeading eyebrow="YOUR RESEARCH" title="我的研究" description="带着具体的问题，比较真正影响你选择的条件。" /><ErrorState error={{ status: 401 }} /></>;
  if (taskId) return <TaskDetail id={decodeRouteSegment(taskId)} />;
  const tasks = list(state.data);
  return <><PageHeading eyebrow="YOUR RESEARCH" title="每一次选择，都有依据。" description="把需求、候选方案和你的判断，留在同一份研究里。"><Button variant="primary" onClick={() => setCreating(true)}><Plus size={16} />新建研究任务</Button></PageHeading><div className="private-notice"><LockKeyhole size={13} />研究任务与笔记仅自己可见</div><DataState state={state}>{tasks.length ? <div className="task-grid">{tasks.map(task => <article className="panel task-card" key={task.id}><div className="task-top"><span className="task-icon"><PanelsTopLeft size={20} /></span><Badge tone={task.status === 'adopted' ? 'green' : 'indigo'}>{STATUSES[task.status] || '研究中'}</Badge><button className="icon-button" aria-label={`编辑 ${task.title}`} onClick={() => setEditing(task)}><Pencil size={14} /></button></div><a className="task-title" href={`#research/${encodeURIComponent(task.id)}`}>{task.title}</a><p>{task.problem || '补充具体场景，让比较更有方向。'}</p><div className="task-condition"><span>必须满足</span>{task.must_have || '尚未填写关键约束'}</div><div className="task-card-footer"><span>{task.candidate_ids?.length || 0} 个候选<span className="footer-dot">·</span>{date(task.updated_at || task.created_at)} 更新</span><a href={`#research/${encodeURIComponent(task.id)}`}>继续研究<ArrowRight size={15} /></a></div></article>)}</div> : <Empty title="从一个具体问题开始" description="例如：为内部业务系统选择可自托管的浏览器自动化方案。" action={<Button variant="primary" onClick={() => setCreating(true)}><Plus size={16} />创建第一份研究</Button>} />}</DataState>{(creating || editing) && <TaskForm task={editing} onClose={() => { setCreating(false); setEditing(null); }} />}</>;
}

function TaskForm({ task, onClose }) { const { mutate } = useApp(); const [busy, setBusy] = useState(false); return <Modal title={task ? '编辑研究任务' : '新建研究任务'} subtitle="先写下问题，其余条件可以在研究中逐步补充。" wide onClose={onClose}><form className="form-body" onSubmit={async e => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); setBusy(true); try { const result = await mutate(task ? `/research-tasks/${task.id}` : '/research-tasks', task ? 'PATCH' : 'POST', data, task ? '研究任务已更新' : '研究任务已创建'); onClose(); if (!task && item(result)?.id) navigate(`research/${item(result).id}`); } catch {} finally { setBusy(false); } }}><Field label="任务名称"><input data-testid="task-title" name="title" required maxLength={120} defaultValue={task?.title || ''} placeholder="例如：选择内部业务系统的浏览器自动化方案" /></Field><Field label="要解决的问题 / 使用场景"><textarea name="problem" rows={3} defaultValue={task?.problem || ''} placeholder="谁会使用？在什么场景下解决什么问题？" /></Field><div className="form-grid"><Field label="必须满足"><textarea name="must_have" rows={3} defaultValue={task?.must_have || ''} placeholder="例如：能够自托管，支持 TypeScript" /></Field><Field label="可以妥协"><textarea name="flexible" rows={3} defaultValue={task?.flexible || ''} placeholder="例如：允许额外维护基础设施" /></Field><Field label="当前最不确定的问题"><textarea name="uncertainties" rows={3} defaultValue={task?.uncertainties || ''} placeholder="哪些条件仍需要实测？" /></Field><Field label="重新评估的触发条件"><textarea name="reevaluate_when" rows={3} defaultValue={task?.reevaluate_when || ''} placeholder="例如：部署方式或许可证发生变化" /></Field><Field label="研究阶段"><select name="phase" defaultValue={task?.phase || 'selection'}><option value="selection">选型期间</option><option value="adopted">采用之后</option></select></Field><Field label="当前判断"><select name="status" defaultValue={task?.status || 'researching'}>{Object.entries(STATUSES).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></Field></div><div className="form-actions"><Button type="button" onClick={onClose}>取消</Button><Button data-testid="save-task" type="submit" variant="primary" busy={busy}>{task ? '保存修改' : '创建研究任务'}<ArrowRight size={15} /></Button></div></form></Modal>; }

function TaskDetail({ id }) {
  const state = useData(`/research-tasks/${encodeURIComponent(id)}/comparison`); const { mutate, notify } = useApp(); const [edit, setEdit] = useState(false); const [add, setAdd] = useState(false); const [deleting, setDeleting] = useState(false); const [mobileCandidate, setMobileCandidate] = useState(''); const result = item(state.data); const task = result?.task; const candidates = result?.candidates || [];
  const remove = async entityId => { try { await mutate(`/research-tasks/${id}/candidates/${entityId}`, 'DELETE', undefined, '已从比较中移除'); } catch {} };
  return <DataState state={state}>{task && <><a href="#research" className="back-link">← 返回我的研究</a><PageHeading eyebrow="PRIVATE RESEARCH" title={task.title} description={task.problem}><Button onClick={() => setEdit(true)}><Pencil size={14} />编辑任务</Button><Button variant="primary" onClick={() => setAdd(true)} disabled={candidates.length >= 5}><Plus size={15} />添加候选</Button></PageHeading><div className="task-detail-meta"><Badge tone="indigo">{STATUSES[task.status]}</Badge><Badge>{task.phase === 'adopted' ? '采用后跟踪' : '选型期间'}</Badge><span><LockKeyhole size={12} />仅自己可见</span><button className="text-button danger-text" onClick={() => setDeleting(true)}>删除任务</button></div><div className="constraints-grid">{[['必须满足', task.must_have], ['可以妥协', task.flexible], ['待确认问题', task.uncertainties], ['重新评估条件', task.reevaluate_when]].map(([label, value]) => <div key={label}><span className="tiny-label">{label}</span><p>{value || '尚未填写'}</p></div>)}</div>{result.warnings?.map((warning, index) => <div className="notice warning" key={index}><Info size={15} />{typeof warning === 'string' ? warning : warning.message}</div>)}<section className="panel comparison-panel"><div className="panel-heading"><h2>围绕条件，逐项比较</h2><span className="muted">{candidates.length} / 5 个候选</span></div><p className="comparison-note">“待核实”表示证据不足，与“不支持”含义不同；比较不产生通用总分。</p>{candidates.length ? <><div className="mobile-candidate-select"><label>当前对比对象<select value={candidates.some(entity => entity.id === mobileCandidate) ? mobileCandidate : candidates[0]?.id} onChange={e => setMobileCandidate(e.target.value)}>{candidates.map(entity => <option value={entity.id} key={entity.id}>{entity.name}</option>)}</select></label></div><div className="comparison-scroll"><table data-testid="comparison" className="comparison-table"><thead><tr><th>比较维度</th>{candidates.map(entity => <th className={(candidates.some(entity => entity.id === mobileCandidate) ? mobileCandidate : candidates[0]?.id) === entity.id ? 'mobile-active' : 'mobile-hidden'} key={entity.id}><EntityMark small entity={entity} /><a href={`#entity/${entity.id}`}>{entity.name}<ArrowUpRight size={12} /></a><button aria-label={`移除候选 ${entity.name}`} className="icon-button" onClick={() => remove(entity.id)}><X size={13} /></button></th>)}</tr></thead><tbody>{(result.rows || []).map(row => <tr key={row.dimension || row.id}><th>{row.label || row.dimension}</th>{candidates.map(entity => { const cell = row.cells?.find(value => value.entity_id === entity.id); return <td key={entity.id} className={(candidates.some(entity => entity.id === mobileCandidate) ? mobileCandidate : candidates[0]?.id) === entity.id ? 'mobile-active' : 'mobile-hidden'}><span className={`support-status ${cell?.status || 'unknown'}`}><CircleDot size={12} />{SUPPORT[cell?.status] || '待核实'}</span><p>{cell?.value || '暂无可核查信息'}</p><small>{cell?.scope || '适用范围待核实'}</small><EvidenceButtons ids={cell?.evidence_ids} /></td>; })}</tr>)}</tbody></table></div>{candidates.length < 2 && <div className="notice"><Info size={14} />再添加至少 1 个候选，形成有意义的方案比较。</div>}</> : <Empty title="添加你的第一个候选" description="每份研究可比较 2—5 个项目或产品。" action={<Button onClick={() => setAdd(true)}><Plus size={15} />添加候选</Button>} />}</section><Notes taskId={task.id} /><section className="panel decision-panel"><div><h2>这次研究，你的判断是？</h2><p>判断会保存在研究任务中，你可以随时重新评估。</p></div><select aria-label="更新研究判断" value={task.status} onChange={async e => { try { await mutate(`/research-tasks/${id}`, 'PATCH', { status: e.target.value }, '研究判断已更新'); } catch {} }}>{Object.entries(STATUSES).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></section>{edit && <TaskForm task={task} onClose={() => setEdit(false)} />}{add && <CandidatePicker task={task} onClose={() => setAdd(false)} />}{deleting && <Confirm title="删除这份研究？" description="研究任务将被删除，此操作不可撤销。" onClose={() => setDeleting(false)} onConfirm={async () => { await mutate(`/research-tasks/${id}`, 'DELETE', undefined, '研究任务已删除'); navigate('research'); }} />}</>}</DataState>;
}

function CandidatePicker({ task, onClose }) { const state = useData('/entities'); const [query, setQuery] = useState(''); const { mutate } = useApp(); const [busy, setBusy] = useState(null); return <Modal title="选择研究候选" subtitle="每份任务最多 5 个候选，建议聚焦相同使用场景。" onClose={onClose}><div className="form-body"><div className="search-field"><Search size={16} /><input placeholder="搜索项目或产品" aria-label="搜索候选" value={query} onChange={e => setQuery(e.target.value)} /></div><DataState state={state}><div className="candidate-list">{list(state.data).filter(entity => !task.candidate_ids?.includes(entity.id) && `${entity.name} ${entity.description}`.toLowerCase().includes(query.toLowerCase())).map(entity => <div className="candidate-option" key={entity.id}><EntityMark small entity={entity} /><div><strong>{entity.name}</strong><p>{entity.description}</p></div><Button busy={busy === entity.id} onClick={async () => { setBusy(entity.id); try { await mutate(`/research-tasks/${task.id}/candidates`, 'POST', { entity_id: entity.id }, '候选已加入研究'); onClose(); } catch {} finally { setBusy(null); } }}><Plus size={15} />加入</Button></div>)}</div></DataState></div></Modal>; }
function AddCandidate({ entity, onClose }) { const state = useData('/research-tasks'); const { mutate } = useApp(); const [newTask, setNewTask] = useState(false); return <Modal title={`将 ${entity.name} 加入研究`} subtitle="选择一份已有任务，保留围绕具体问题的比较。" onClose={onClose}><div className="form-body"><DataState state={state}>{list(state.data).length ? <div className="candidate-list">{list(state.data).map(task => <div className="candidate-option" key={task.id}><PanelsTopLeft size={19} /><div><strong>{task.title}</strong><p>{task.candidate_ids?.length || 0} 个候选 · {STATUSES[task.status]}</p></div><Button disabled={task.candidate_ids?.includes(entity.id) || task.candidate_ids?.length >= 5} onClick={async () => { try { await mutate(`/research-tasks/${task.id}/candidates`, 'POST', { entity_id: entity.id }, '已加入研究候选'); onClose(); } catch {} }}>{task.candidate_ids?.includes(entity.id) ? '已加入' : '加入'}</Button></div>)}</div> : <Empty title="先建立一份研究任务" description="写下要解决的问题，再添加候选进行比较。" />}</DataState><Button onClick={() => setNewTask(true)}><Plus size={15} />新建研究任务</Button></div>{newTask && <TaskForm onClose={() => setNewTask(false)} />}</Modal>; }

function Notes({ entityId, taskId }) { const { session, setLogin, mutate } = useApp(); const state = useData(session.user ? `/notes?${new URLSearchParams({ ...(entityId ? { entity_id: entityId } : {}), ...(taskId ? { task_id: taskId } : {}) })}` : null); const [body, setBody] = useState(''); const [status, setStatus] = useState('watching'); const [editing, setEditing] = useState(null); const [busy, setBusy] = useState(false); const [deleting, setDeleting] = useState(null); const notes = list(state.data).filter(note => (!entityId || note.entity_id === entityId) && (!taskId || note.task_id === taskId)); return <section className="panel content-panel notes-panel"><div className="panel-title-row"><h2>我的研究笔记</h2><span><LockKeyhole size={12} />仅自己可见</span></div>{session.user ? <><form onSubmit={async e => { e.preventDefault(); setBusy(true); try { await mutate(editing ? `/notes/${editing}` : '/notes', editing ? 'PATCH' : 'POST', { body, status, ...(entityId ? { entity_id: entityId } : {}), ...(taskId ? { task_id: taskId } : {}) }, editing ? '笔记已更新' : '私有笔记已保存'); setBody(''); setEditing(null); } catch {} finally { setBusy(false); } }}><textarea data-testid="note-body" required rows={3} value={body} onChange={e => setBody(e.target.value)} placeholder="记下实测结果、待验证问题，或一句当前判断…" aria-label="私有笔记内容" /><div className="note-actions"><select aria-label="笔记判断状态" value={status} onChange={e => setStatus(e.target.value)}>{Object.entries(STATUSES).map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select>{editing && <Button type="button" onClick={() => { setEditing(null); setBody(''); }}>取消编辑</Button>}<Button data-testid="save-note" type="submit" variant="primary" busy={busy}>{editing ? '保存修改' : '保存笔记'}</Button></div></form><DataState state={state}>{notes.map(note => <div className="note-item" key={note.id}><div><Badge>{STATUSES[note.status] || note.status}</Badge><time>{datetime(note.created_at)}</time><button className="icon-button" aria-label="编辑笔记" onClick={() => { setEditing(note.id); setBody(note.body); setStatus(note.status || 'watching'); }}><Pencil size={13} /></button><button className="icon-button" aria-label="删除笔记" onClick={() => setDeleting(note)}><Trash2 size={13} /></button></div><p>{note.body}</p></div>)}</DataState></> : <p className="muted"><button className="text-button" onClick={() => setLogin(true)}>登录</button>后，保存只属于你的研究判断。</p>}{deleting && <Confirm title="删除这条笔记？" description="删除后无法恢复。" onClose={() => setDeleting(null)} onConfirm={() => mutate(`/notes/${deleting.id}`, 'DELETE', undefined, '笔记已删除')} />}</section>; }

function WatchForm({ entity, watch, onClose }) { const { mutate } = useApp(); const [types, setTypes] = useState(watch?.event_types || ['release', 'capability', 'pricing', 'deployment', 'issue']); const [busy, setBusy] = useState(false); return <Modal title={watch ? '调整跟踪设置' : `持续跟踪 ${entity?.name || '这个对象'}`} subtitle="写下为什么关注，让后续变化与原来的判断保持联系。" onClose={onClose}><form className="form-body" onSubmit={async e => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); setBusy(true); try { await mutate(watch ? `/watches/${watch.id}` : '/watches', watch ? 'PATCH' : 'POST', { ...data, ...(watch ? {} : { entity_id: entity.id }), event_types: types }, watch ? '跟踪设置已更新' : '已加入持续跟踪'); onClose(); } catch {} finally { setBusy(false); } }}><Field label="关注原因"><textarea data-testid="watch-reason" name="reason" rows={3} defaultValue={watch?.reason || ''} placeholder="例如：正在评估自托管方案，关注部署和许可证条件变化。" /></Field><fieldset className="event-checkboxes"><legend>关心哪些变化</legend>{Object.entries(EVENT_TYPES).map(([value, label]) => <label key={value}><input type="checkbox" checked={types.includes(value)} onChange={e => setTypes(previous => e.target.checked ? [...previous, value] : previous.filter(type => type !== value))} />{label}</label>)}</fieldset><Field label="摘要频率" help="邮件需在账户偏好中单独同意订阅。"><select name="frequency" defaultValue={watch?.frequency || 'weekly'}><option value="weekly">每周摘要</option><option value="daily">每日摘要</option><option value="in_app">仅站内查看</option></select></Field><div className="form-actions"><Button type="button" onClick={onClose}>取消</Button><Button data-testid="save-watch" type="submit" variant="primary" busy={busy}>{watch ? '保存设置' : '开始跟踪'}<Telescope size={15} /></Button></div></form></Modal>; }
function Watches() { const { session, mutate } = useApp(); const state = useData(session.user ? '/watches' : null); const [editing, setEditing] = useState(null); const [deleting, setDeleting] = useState(null); const watches = list(state.data); return <><PageHeading eyebrow="FOLLOW WHAT MATTERS" title="自上次查看，又有什么变化？" description="从当初的关注原因出发，重新判断哪些变化与你有关。"><a className="button secondary" href="#entities"><Plus size={15} />发现跟踪对象</a></PageHeading>{!session.user ? <ErrorState error={{ status: 401 }} /> : <DataState state={state}>{watches.length ? <div className="watch-list">{watches.map(watch => <section className="panel watch-card" key={watch.id}><div className="watch-header"><EntityMark entity={watch.entity || { name: watch.entity_id }} /><div><a href={`#entity/${watch.entity_id}`}>{watch.entity?.name || watch.entity_id}</a><p>{({ daily: '每日摘要', weekly: '每周摘要', in_app: '仅站内查看' })[watch.frequency]}<span className="footer-dot">·</span>{watch.paused ? '跟踪已暂停' : '持续跟踪中'}</p></div><Badge tone={watch.unread_count ? 'indigo' : 'neutral'}>{watch.unread_count || 0} 条未读</Badge><button className="icon-button" title="调整跟踪设置" aria-label="调整跟踪设置" onClick={() => setEditing(watch)}><SlidersHorizontal size={16} /></button><button className="icon-button" title={watch.paused ? '恢复跟踪' : '暂停跟踪'} aria-label={watch.paused ? '恢复跟踪' : '暂停跟踪'} onClick={async () => { try { await mutate(`/watches/${watch.id}`, 'PATCH', { paused: !watch.paused }, watch.paused ? '已恢复跟踪' : '已暂停跟踪'); } catch {} }}>{watch.paused ? <Play size={15} /> : <Pause size={15} />}</button><button className="icon-button" title="取消跟踪" aria-label="取消跟踪" onClick={() => setDeleting(watch)}><Trash2 size={15} /></button></div><div className="watch-reason"><span>当初为什么关注</span><p>{watch.reason || '尚未填写关注原因，可在设置中补充。'}</p></div><div className="watch-event-types">{watch.event_types?.map(type => <Badge key={type}>{EVENT_TYPES[type] || type}</Badge>)}</div>{watch.events?.length ? <div className="watch-events">{watch.events.map(event => <EventCard key={event.id} event={event} />)}</div> : <div className="no-changes"><CheckCheck size={18} />本期没有发现已核查的重要变化。</div>}<div className="watch-footer"><span>上次查看：{datetime(watch.last_read_at)}</span><Button onClick={async () => { try { await mutate(`/watches/${watch.id}/read`, 'POST', {}, '已标记为已读'); } catch {} }}><CheckCheck size={14} />标为已读</Button></div></section>)}</div> : <Empty title="跟踪那些可能改变判断的事" description="关注一个项目，保存原因，并选择你关心的变化。" action={<a className="button primary" href="#entities">选择跟踪对象<ArrowRight size={15} /></a>} />}</DataState>}{editing && <WatchForm watch={editing} entity={editing.entity} onClose={() => setEditing(null)} />}{deleting && <Confirm title="取消跟踪这个对象？" description="停止跟踪后，不再为这个对象整理新的变化摘要。" onClose={() => setDeleting(null)} onConfirm={() => mutate(`/watches/${deleting.id}`, 'DELETE', undefined, '已取消跟踪')} />}</>; }

function Digests({ route }) { const { session, mutate } = useApp(); const state = useData(session.user ? '/digests' : null); const [selected, setSelected] = useState(route.split('/')[1] ? decodeRouteSegment(route.split('/')[1]) : null); useEffect(() => { const id = route.split('/')[1]; if (id) setSelected(decodeRouteSegment(id)); }, [route]); useEffect(() => { if (selected) track('digest_view', {}, true); }, [selected]); const [busy, setBusy] = useState(false); const detail = useData(selected ? `/digests/${selected}` : null); const digest = item(detail.data); return <><PageHeading eyebrow="CHANGES, IN CONTEXT" title="变化摘要" description="只整理与你的跟踪对象相关、已经核查的变化。"><Button variant="primary" disabled={!session.user} busy={busy} onClick={async () => { setBusy(true); try { const result = await mutate('/digests/generate', 'POST', {}, '摘要整理已完成'); const created = item(result); if (created?.id) setSelected(created.id); } catch {} finally { setBusy(false); } }}><RefreshCw size={15} />整理本期摘要</Button></PageHeading>{!session.user ? <ErrorState error={{ status: 401 }} /> : <DataState state={state}>{list(state.data).length ? <div className="digest-grid">{list(state.data).map(row => <button className="panel digest-card" key={row.id} onClick={() => setSelected(row.id)}><span className="digest-icon"><FileText size={26} strokeWidth={1.3} /></span><div><span className="tiny-label">{date(row.created_at)} · 变化摘要</span><h2>{row.title}</h2><p>{row.events?.length ?? row.event_count ?? 0} 条已收录变化{row.is_demo ? ' · 演示内容' : ''}</p></div><ArrowRight size={20} /></button>)}</div> : <Empty title="让重要变化汇成一份摘要" description="先关注项目，再整理已核查的新事件。没有新变化时，不重复生成摘要。" />}</DataState>}{selected && <Modal title={digest?.title || '变化摘要'} subtitle={digest ? datetime(digest.created_at) : ''} wide onClose={() => setSelected(null)}><div className="form-body"><DataState state={detail}>{digest?.events?.length ? digest.events.map(event => <EventCard key={event.id} event={event} />) : <Empty title="本期没有新的已核查变化" description="无需重复阅读旧介绍。" />}</DataState></div></Modal>}</>; }

function Confirm({ title, description, onClose, onConfirm }) { const [busy, setBusy] = useState(false); return <Modal title={title} onClose={onClose}><div className="form-body"><p className="muted">{description}</p><div className="form-actions"><Button onClick={onClose}>取消</Button><Button variant="danger" busy={busy} onClick={async () => { setBusy(true); try { await onConfirm(); onClose(); } catch {} finally { setBusy(false); } }}>确认</Button></div></div></Modal>; }

function Settings() {
  const { session, mutate, notify } = useApp(); const [deleting, setDeleting] = useState(false); const [email, setEmail] = useState(session.user?.email_opt_in || false); const emailUnavailable = session.mode === 'production' && !session.user?.email; useEffect(() => setEmail(session.user?.email_opt_in || false), [session.user?.email_opt_in]);
  return <><PageHeading eyebrow="YOUR WORKSPACE" title="账户与偏好" description="研究属于你，通知也由你决定。" />{session.user ? <div className="settings-layout"><section className="panel content-panel"><h2>个人工作区</h2><div className="profile-card"><span className="avatar large">{session.user.name?.[0] || '研'}</span><div><h3>{session.user.name}</h3><p>{session.user.email || (session.mode === 'demo' ? '独立演示账户' : '尚未提供公开邮箱')}</p><Badge>{({ admin: '管理员', editor: '编辑', user: '研究员' })[session.user.role]}</Badge></div></div><p className="muted">账户标识：<code>{session.user.id}</code></p><Button onClick={async () => { try { await mutate('/auth/logout', 'POST', {}, '已退出工作区'); navigate('discover'); } catch {} }}><LogOut size={15} />退出登录</Button></section><section className="panel content-panel"><h2>邮件通知</h2><p className="section-description">登录与邮件订阅分开授权；通知频率在每个跟踪对象中调整。</p><label className="check-label"><input type="checkbox" disabled={emailUnavailable} checked={emailUnavailable ? false : email} onChange={e => setEmail(e.target.checked)} />我同意接收跟踪对象的变化摘要邮件</label><Button disabled={emailUnavailable} onClick={async () => { try { await mutate('/preferences', 'PATCH', { email_opt_in: email }, '邮件偏好已保存'); } catch {} }}>保存通知偏好</Button>{emailUnavailable && <div className="notice"><Info size={14} />GitHub 公开资料尚未提供邮箱，当前可使用站内摘要；添加公开邮箱并重新登录后再订阅。</div>}{session.mode === 'demo' && <div className="notice"><Info size={14} />演示环境不向外部邮箱实际发送邮件。</div>}</section><section className="panel content-panel"><h2>我的数据</h2><p className="section-description">导出自己的研究记录，或删除账户及关联私有数据。</p><div className="button-row"><Button onClick={async () => { try { const data = await api('/account/export'); const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `radar-workspace-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); notify('工作区数据已导出'); } catch (error) { notify(error.message, true); } }}><Download size={15} />导出我的数据</Button><Button variant="danger" onClick={() => setDeleting(true)}><Trash2 size={15} />删除账户</Button></div></section></div> : <ErrorState error={{ status: 401 }} />}{deleting && <Confirm title="永久删除这个账户？" description="账户及关联的私有研究、关注、笔记等数据将被删除。此操作不可撤销，建议先导出数据。" onClose={() => setDeleting(false)} onConfirm={async () => { await mutate('/account', 'DELETE', undefined, '账户已删除'); navigate('discover'); }} />}</>;
}

function Method() {
  const { session } = useApp();
  const contextState = useData('/feed?kind=product&limit=1');
  const principles = [
    { icon: Compass, title: '有限样本，明确范围', text: '发现页展示本平台跟踪样本，并非 GitHub 官方 Trending，也不代表全网项目。首版聚焦业务自动化方向。没有可比较的增长时，按名称浏览，不把项目顺序当作增长排名。' },
    { icon: Link2, title: '保留出处与核查时间', text: '重要能力、版本条件与项目关系关联原始证据。采集时间、来源发布时间和人工核查时间分别记录。今天采集到的版本，可能早于今天发布。' },
    { icon: Layers3, title: '仓库、产品与事件分开理解', text: '收录一个开源仓库，不等于已建立独立产品档案。取得版本发布记录后，还需要审核才会成为公开事件。产品或变化暂未展示，不等于项目没有发布或更新。' },
    { icon: CircleHelp, title: '未知与不支持，含义不同', text: '能力缺少证据时标为待核实；增长缺少早期记录时显示待对比，不补零。Star 表示累计关注，不等于用户数、收入或产品质量。' },
    { icon: ShieldCheck, title: '关系需要证据确认', text: '名称相近或用途类似不能自动确认官方关系。开源版、托管版与企业版也可能有不同能力和使用条件，不能混写。' },
    { icon: Telescope, title: '没有变化，也可以不发送', text: '变化摘要围绕你的跟踪对象整理。来源采集失败与没有发现已核查的重要变化分别处理；待审核的版本不会提前进入已发布摘要。' },
  ];
  return <><PageHeading eyebrow="EVIDENCE BEFORE CONCLUSIONS" title="结论有出处，未知有边界。" description="了解每个数字和状态的含义，再用它们帮助判断。" />
    <section className="panel content-panel method-growth"><h2>为什么已有 Stars，却看不到最近增长？</h2><p>一次采集只能告诉我们“当时累计有多少 Stars”。要知道最近 24 小时或 7 天的增长，必须取得对应时间前后的两份记录。</p><div className="growth-calculation" aria-label="仅用于解释的计算示例"><span>约 24 小时前<strong>1,000 Stars</strong></span><span>最新一次记录<strong>1,030 Stars</strong></span><span>24 小时净变化<strong>+30</strong></span></div><p className="calculation-caption">以上数字仅为计算示例，不是任何项目的实测数据。</p><dl className="growth-glossary"><div><dt>待对比</dt><dd>已经取得当前总量，但缺少约 24 小时前或 7 天前的有效记录。不是零增长，也不是本次采集失败。</dd></div><div><dt>暂不能比</dt><dd>已有记录的时间间隔或统计范围不适合当前比较，需要取得合适的对照记录。</dd></div><div><dt>暂无总量</dt><dd>尚未取得有效的 Star 记录，应先查看来源采集情况。</dd></div></dl><div className="notice"><Info size={16} /><span>{scheduleExplanation(contextState.data?.collection)}</span></div></section>
    <div className="method-grid">{principles.map(({ icon: Icon, title, text }) => <section key={title} className="panel content-panel method-card"><span className="method-icon"><Icon size={23} strokeWidth={1.5} /></span><h2>{title}</h2><p>{text}</p></section>)}</div>
    <section className="panel content-panel"><h2>当前环境</h2><p>{session.mode === 'demo' ? '当前使用独立的演示数据库。演示项目指标、能力判断和变化事件用于验证产品流程，不是对当前真实状态的确认。演示数据不与正式采集样本混合排序。' : '页面信息以各条记录的来源与实际观察时间为准。是否启用持续采集，要看采集状态中的说明；经过一天或一周，并不自动意味着又采集了新数据。'}</p><p className="muted">发现不准确的内容，可在登录开放后，通过项目详情或证据面板提交纠错，审核后再更新公开记录。</p></section>
  </>;
}

function Admin() {
  const { session, mutate } = useApp(); const state = useData(session.user && ['admin', 'editor'].includes(session.user.role) ? '/admin/overview' : null); const [tab, setTab] = useState('sources'); const [action, setAction] = useState(null); const [form, setForm] = useState(null); const overview = item(state.data) || {};
  if (!session.user) return <><PageHeading title="运营后台" description="审核事实、处理异常，保留每次操作的依据。" /><ErrorState error={{ status: 401 }} /></>;
  if (!['admin', 'editor'].includes(session.user.role)) return <Empty title="需要编辑或管理员权限" description="公开研究内容仍可正常浏览。" />;
  const tabs = [{ id: 'sources', label: '来源与任务' }, { id: 'review', label: '内容审核' }, { id: 'business', label: '成本与试点' }, { id: 'audit', label: '操作记录' }].filter(value => value.id !== 'business' || session.user.role === 'admin');
  return <><PageHeading eyebrow="OPERATIONS WORKSPACE" title="让研究持续可靠地运行。" description="来源状态、内容核查与真实交付成本，放在同一处查看。"><Button variant="primary" onClick={() => setForm('editorial')}><Plus size={15} />录入研究资料</Button></PageHeading><div className="admin-stats">{[['来源', overview.sources?.length], ['待审核事件', overview.pending_events?.length], ['纠错记录', overview.corrections?.length], ['日预算', overview.budget?.daily_limit]].map(([label, value]) => <div className="panel" key={label}><span>{label}</span><strong>{number(value)}</strong></div>)}</div><div className="admin-tabs">{tabs.map(value => <button className={tab === value.id ? 'active' : ''} key={value.id} onClick={() => setTab(value.id)}>{value.label}</button>)}</div><DataState state={state}>{tab === 'sources' ? <><section className="panel content-panel"><h2>采集来源</h2><div className="admin-list">{overview.sources?.map(source => <div className="admin-row" key={source.id}><div><h3>{source.name || source.id}<Badge tone={['active', 'approved'].includes(source.status) ? 'green' : 'amber'}>{source.status}</Badge></h3><p>{source.permission_status || '权限待核查'}{source.last_success_at ? ` · 最近成功 ${datetime(source.last_success_at)}` : ''}{source.last_error ? ` · ${source.last_error}` : ''}</p></div><Button disabled={session.user.role !== 'admin'} title={session.user.role !== 'admin' ? '来源启用和停用需要管理员权限' : undefined} onClick={() => setAction({ title: ['active', 'approved'].includes(source.status) ? '暂停这个来源' : '核查权限并启用来源', path: `/admin/sources/${source.id}`, method: 'PATCH', body: { status: ['active', 'approved'].includes(source.status) ? 'paused' : 'active' } })}>{['active', 'approved'].includes(source.status) ? <Pause size={14} /> : <Play size={14} />}{['active', 'approved'].includes(source.status) ? '暂停来源' : '审核并启用'}</Button></div>)}</div></section><section className="panel content-panel"><h2>运行任务</h2>{overview.jobs?.length ? overview.jobs.map(job => <div className="admin-row" key={job.id}><div><h3>{job.type || job.name || job.id}<Badge>{job.status}</Badge></h3><p>{job.error || job.last_error || job.message || '暂无异常详情'}</p></div><Button disabled={session.user.role !== 'admin'} title={session.user.role !== 'admin' ? '重试采集任务需要管理员权限' : undefined} onClick={async () => { try { await mutate(`/admin/jobs/${job.id}/retry`, 'POST', {}, '任务已进入重试队列'); } catch {} }}><RefreshCw size={14} />重试</Button></div>) : <p className="muted">暂无运行任务。</p>}</section></> : tab === 'review' ? <><section className="panel content-panel"><h2>证据审核</h2>{overview.evidence?.length ? overview.evidence.map(evidence => <div className="admin-row" key={evidence.id}><div><h3>{evidence.title}<Badge>{evidence.review_status}</Badge></h3><p>{evidence.source_name || evidence.source_id} · {datetime(evidence.fetched_at)}</p><EvidenceButtons ids={[evidence.id]} records={[evidence]} /></div><div className="button-row"><Button disabled={evidence.review_status === 'published'} onClick={() => setAction({ title: '核查并发布证据', path: `/admin/evidence/${evidence.id}/review`, body: { status: 'published' } })}>核查通过</Button><Button onClick={() => setAction({ title: '拒绝这条证据', path: `/admin/evidence/${evidence.id}/review`, body: { status: 'rejected' } })}>拒绝</Button></div></div>) : <p className="muted">暂无证据记录，先录入原始出处再审核发布。</p>}</section><section className="panel content-panel"><h2>待审核事件</h2>{overview.pending_events?.length ? overview.pending_events.map(event => <div className="review-row" key={event.id}><EventCard event={event} /><div className="button-row"><Button onClick={() => setAction({ title: '审核并发布事件', path: `/admin/events/${event.id}/review`, body: { action: 'publish' } })}><Check size={14} />核查发布</Button><Button onClick={() => setAction({ title: '撤回事件', path: `/admin/events/${event.id}/review`, body: { action: 'retract' } })}>撤回</Button><Button onClick={() => setAction({ title: '更正事件', path: `/admin/events/${event.id}/review`, body: { action: 'correct' }, editableEvent: event })}>更正</Button></div></div>) : <p className="muted">暂无待审核事件。</p>}</section><section className="panel content-panel"><h2>关系核查</h2>{overview.relations?.length ? overview.relations.map(relation => <div className="admin-row" key={relation.id}><div><h3>{relation.source_name || relation.entity_id} → {relation.target_name || relation.target_entity_id}</h3><p>{relation.type || relation.relation_type} · {relation.status}</p><EvidenceButtons ids={relation.evidence_ids} /></div><div className="button-row"><Button onClick={() => setAction({ title: '确认关系', path: `/admin/relations/${relation.id}/review`, body: { status: 'confirmed' } })}>确认</Button><Button onClick={() => setAction({ title: '否定关系', path: `/admin/relations/${relation.id}/review`, body: { status: 'rejected' } })}>否定</Button><Button onClick={() => setAction({ title: '标记需要复核', path: `/admin/relations/${relation.id}/review`, body: { status: 'needs_review' } })}>待复核</Button></div></div>) : <p className="muted">暂无关系记录。</p>}</section><section className="panel content-panel"><h2>用户纠错</h2>{overview.corrections?.length ? overview.corrections.map(correction => <div className="admin-row" key={correction.id}><div><h3>{correction.description}</h3><p>{correction.status || 'pending'} · {datetime(correction.created_at)}</p>{correction.url && <External href={correction.url}>用户提供的出处</External>}</div><div className="button-row"><Button onClick={() => setAction({ title: '标记纠错已解决', path: `/admin/corrections/${correction.id}/review`, body: { status: 'resolved' } })}>已解决</Button><Button onClick={() => setAction({ title: '拒绝纠错', path: `/admin/corrections/${correction.id}/review`, body: { status: 'rejected' } })}>拒绝</Button></div></div>) : <p className="muted">暂无纠错记录。</p>}</section><section className="panel content-panel"><h2>来源删除与撤回</h2><p className="section-description">根据证据标识撤回来源内容，并传播到依赖该证据的衍生记录。</p><Button variant="danger" disabled={session.user.role !== 'admin'} onClick={() => setForm('withdraw')}>处理证据删除请求</Button></section></> : tab === 'business' ? <><section className="panel content-panel"><div className="panel-title-row"><h2>交付成本</h2><Button onClick={() => setForm('cost')}><Plus size={14} />记录成本</Button></div><div className="table-scroll"><table className="simple-table"><thead><tr><th>分类</th><th>金额</th><th>人工分钟</th><th>说明</th></tr></thead><tbody>{overview.costs?.map((cost, index) => <tr key={cost.id || index}><td>{cost.category}</td><td>¥ {number(cost.amount)}</td><td>{number(cost.minutes)}</td><td>{cost.note || '—'}</td></tr>)}</tbody></table></div>{!overview.costs?.length && <p className="muted">尚未记录成本，不能据此认定成本为零。</p>}</section><section className="panel content-panel"><div className="panel-title-row"><h2>已核款试点订单</h2><Button onClick={() => setForm('order')}><Plus size={14} />记录订单</Button></div><p className="section-description">仅记录已人工核实的真实收款。这里不会发起支付，也不会自动续费。</p>{overview.orders?.map(order => <div className="admin-row" key={order.id}><div><h3>{order.reference || order.id}<Badge>{order.status}</Badge></h3><p>{order.user_id} · {order.currency || 'CNY'} {number(order.amount)} · {order.expires_at ? `到期 ${datetime(order.expires_at)}` : ''}</p></div><Button disabled={order.status === 'refunded'} onClick={() => setAction({ title: '记录已完成退款', path: `/admin/orders/${order.id}/refund`, body: {} })}>登记退款</Button></div>)}{!overview.orders?.length && <p className="muted">暂无已核款订单。</p>}</section><section className="panel content-panel"><div className="panel-title-row"><h2>预算阈值</h2><Button onClick={() => setForm('budget')}>调整预算</Button></div><p>每日上限 ¥ {number(overview.budget?.daily_limit)} · 每月上限 ¥ {number(overview.budget?.monthly_limit)}</p><p className="muted">超出预算时保留已有研究内容，暂停相关新分析。</p></section><section className="panel content-panel"><h2>行为与质量观察</h2><div className="metrics-grid">{Object.entries({ ...overview.metrics, ...overview.quality }).filter(([, value]) => ['string', 'number'].includes(typeof value)).map(([key, value]) => <div key={key}><span>{({ task_created: '创建研究任务', source_opened: '查看证据', watch_added: '建立跟踪', active_users: '活跃账户', total_users: '账户数', total_tasks: '研究任务数', total_watches: '跟踪数', total_events: '事件数' })[key] || key}</span><strong>{value}</strong></div>)}</div></section></> : <section className="panel content-panel"><h2>审核与运行操作记录</h2>{overview.audit?.length ? overview.audit.map((entry, index) => <div className="audit-row" key={entry.id || index}><Clock3 size={15} /><div><strong>{entry.action || entry.type}</strong><p>{entry.reason || entry.details?.reason || (typeof entry.details === 'string' ? entry.details : '')}</p><small>{entry.actor_name || entry.user_id || entry.actor_id || '系统'} · {datetime(entry.created_at || entry.at)}</small></div></div>) : <p className="muted">暂无操作记录。</p>}</section>}</DataState>{action && <AdminAction action={action} onClose={() => setAction(null)} />}{form === 'editorial' ? <EditorialForm overview={overview} onClose={() => setForm(null)} /> : form && <AdminForm type={form} budget={overview.budget} onClose={() => setForm(null)} />}</>;
}
function AdminAction({ action, onClose }) { const { mutate } = useApp(); const [busy, setBusy] = useState(false); return <Modal title={action.title} subtitle="记录操作依据；来源启用需核查条款、允许使用范围与保留期限。" onClose={onClose}><form className="form-body" onSubmit={async e => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); setBusy(true); try { await mutate(action.path, action.method || 'POST', { ...action.body, ...data }, '操作已记录'); onClose(); } catch {} finally { setBusy(false); } }}><Field label="操作原因 / 核查依据"><textarea required name="reason" rows={4} minLength={3} placeholder="说明核查的原始出处及本次操作的原因…" /></Field>{action.editableEvent && <><Field label="更正后的标题"><input name="title" required defaultValue={action.editableEvent.title} /></Field><Field label="更正后的说明"><textarea name="summary" required rows={4} defaultValue={action.editableEvent.summary} /></Field></>}<div className="form-actions"><Button type="button" onClick={onClose}>取消</Button><Button type="submit" variant="primary" busy={busy}>确认并记录</Button></div></form></Modal>; }
function AdminForm({ type, budget, onClose }) { const { mutate } = useApp(); const [busy, setBusy] = useState(false); const titles = { cost: '记录交付成本', order: '记录已核款订单', budget: '调整预算阈值', withdraw: '删除证据并撤回衍生内容' }; return <Modal title={titles[type]} onClose={onClose}><form className="form-body" onSubmit={async e => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); for (const field of ['amount', 'minutes', 'daily_limit', 'monthly_limit']) if (data[field] !== undefined) data[field] = Number(data[field]); if (type === 'order') { data.currency = 'CNY'; data.days = 30; } let path = { cost: '/admin/costs', order: '/admin/orders', budget: '/admin/budget', withdraw: `/admin/evidence/${encodeURIComponent(data.evidence_id)}/delete` }[type]; if (type === 'withdraw') delete data.evidence_id; setBusy(true); try { await mutate(path, type === 'budget' ? 'PATCH' : 'POST', data, '记录已保存'); onClose(); } catch {} finally { setBusy(false); } }}>
    {type === 'cost' && <><Field label="成本分类"><select name="category"><option value="editorial">共享编辑</option><option value="support">用户支持</option><option value="model">模型调用</option><option value="infrastructure">基础设施</option><option value="acquisition">获客</option><option value="other">其他</option></select></Field><Field label="金额（元）"><input name="amount" type="number" min="0" step="0.01" required /></Field><Field label="人工时间（分钟）"><input name="minutes" type="number" min="0" defaultValue="0" required /></Field><Field label="说明"><textarea name="note" required rows={3} /></Field></>}
    {type === 'order' && <><div className="notice warning"><Info size={15} />请在真实收款核验完成后记录。记录30天试点服务期限；当前版本不自动限制功能额度。</div><Field label="用户标识"><input name="user_id" required placeholder="填写已核款账户的用户标识" /></Field><Field label="实收金额（元）"><input name="amount" type="number" min="0.01" step="0.01" required /></Field><Field label="收款凭证 / 订单参考号"><input name="reference" required /></Field></>}
    {type === 'budget' && <><Field label="每日预算上限（元）"><input name="daily_limit" type="number" min="0" step="0.01" defaultValue={budget?.daily_limit} required /></Field><Field label="每月预算上限（元）"><input name="monthly_limit" type="number" min="0" step="0.01" defaultValue={budget?.monthly_limit} required /></Field></>}
    {type === 'withdraw' && <><Field label="证据标识"><input name="evidence_id" required /></Field><Field label="删除依据"><textarea name="reason" required rows={4} minLength={3} placeholder="记录来源删除请求与处理依据" /></Field></>}
    <div className="form-actions"><Button type="button" onClick={onClose}>取消</Button><Button type="submit" variant={type === 'withdraw' ? 'danger' : 'primary'} busy={busy}>确认保存</Button></div></form></Modal>; }

function EditorialForm({ overview, onClose }) {
  const { mutate, session } = useApp();
  const [type, setType] = useState('entity');
  const [entityId, setEntityId] = useState('');
  const [evidenceIds, setEvidenceIds] = useState([]);
  const [busy, setBusy] = useState(false);
  const entitiesState = useData('/entities');
  const entities = overview.entities?.length ? overview.entities : list(entitiesState.data);
  const sources = overview.sources || [];
  const evidences = (overview.evidence || []).filter(evidence => !entityId || !evidence.entity_id || evidence.entity_id === entityId);
  const options = { entity: '项目 / 产品', evidence: '原始证据', event: '变化事件', assertion: '能力判断', edition: '版本 / 套餐', relation: '对象关系', source: '数据来源' };
  return <Modal title="录入研究资料" subtitle="从原始出处开始建档。证据与事件先保存为待审核内容。" wide onClose={onClose}><form className="form-body" onSubmit={async event => {
    event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget));
    for (const field of Object.keys(data)) if (data[field] === '') delete data[field];
    if (['event', 'assertion', 'edition', 'relation'].includes(type)) data.evidence_ids = evidenceIds;
    if (data.price !== undefined) data.price = Number(data.price); if (data.published_at) data.published_at = new Date(data.published_at).toISOString();
    const routes = { entity: 'entities', evidence: 'evidence', event: 'events', assertion: 'assertions', edition: 'editions', relation: 'relations', source: 'sources' };
    setBusy(true); try { await mutate(`/admin/${routes[type]}`, 'POST', data, '资料已保存，请按需继续核查发布'); onClose(); } catch {} finally { setBusy(false); }
  }}><div className="editorial-tabs">{Object.entries(options).filter(([value]) => value !== 'source' || session.user?.role === 'admin').map(([value, label]) => <button key={value} className={type === value ? 'active' : ''} type="button" onClick={() => { setType(value); setEntityId(''); setEvidenceIds([]); }}>{label}</button>)}</div>
    {!['entity', 'source'].includes(type) && <Field label="对应项目或产品"><select name="entity_id" required value={entityId} onChange={event => { setEntityId(event.target.value); setEvidenceIds([]); }}><option value="">请选择对象</option>{entities.map(entity => <option key={entity.id} value={entity.id}>{entity.name}</option>)}</select></Field>}
    {type === 'entity' && <><div className="form-grid"><Field label="对象类型"><select name="kind"><option value="repository">开源仓库</option><option value="product">产品</option></select></Field><Field label="名称"><input name="name" required maxLength={160} /></Field><Field label="稳定短名称" help="使用小写英文、数字和连字符。"><input name="slug" required pattern="[a-z0-9][a-z0-9-]*" placeholder="my-project" /></Field><Field label="研究方向"><input name="topic" required placeholder="浏览器自动化" /></Field><Field label="维护方 / 仓库所有者"><input name="owner" /></Field><Field label="主要语言"><input name="language" /></Field><Field label="许可证"><input name="license" /></Field><Field label="官方网站"><input name="website" type="url" placeholder="https://…" /></Field><Field label="公开仓库"><input name="repository_url" type="url" placeholder="https://github.com/…" /></Field><Field label="官方文档"><input name="docs_url" type="url" placeholder="https://…" /></Field></div><Field label="一句话描述"><textarea name="description" required rows={3} /></Field></>}
    {type === 'evidence' && <><Field label="数据来源"><select name="source_id" required><option value="">请选择来源</option>{sources.map(source => <option key={source.id} value={source.id}>{source.name || source.id}</option>)}</select></Field><Field label="证据标题"><input name="title" required /></Field><Field label="原始出处 URL"><input name="url" type="url" required placeholder="https://…" /></Field><Field label="相关原文摘录"><textarea name="excerpt" required rows={5} placeholder="保留与判断直接有关的原文，注明范围与条件。" /></Field><Field label="来源发布时间（选填）"><input name="published_at" type="datetime-local" /></Field><div className="notice"><Info size={14} />保存后需在「内容审核 → 证据审核」中核查通过，才能支持公开判断。</div></>}
    {type === 'event' && <><Field label="事件类型"><select name="type">{Object.entries(EVENT_TYPES).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></Field><Field label="变化标题"><input name="title" required /></Field><Field label="发生了什么 / 影响与未知"><textarea name="summary" required rows={5} /></Field></>}
    {type === 'assertion' && <><div className="form-grid"><Field label="比较维度标识"><input name="dimension" required placeholder="self_hosting" /></Field><Field label="维度名称"><input name="label" required placeholder="自托管能力" /></Field></div><Field label="判断状态"><select name="status">{Object.entries(SUPPORT).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></Field><Field label="有依据的判断"><textarea name="value" required rows={3} /></Field><Field label="适用版本、套餐与范围"><textarea name="scope" required rows={2} /></Field></>}
    {type === 'edition' && <><div className="form-grid"><Field label="版本 / 套餐名称"><input name="name" required placeholder="社区版" /></Field><Field label="部署方式"><select name="deployment"><option value="self_hosted">本地自托管</option><option value="cloud">云端托管</option><option value="hybrid">混合部署</option><option value="unknown">尚未确认</option></select></Field><Field label="价格（未知请留空）"><input name="price" type="number" min="0" step="0.01" /></Field><Field label="币种"><select name="currency"><option value="CNY">人民币 CNY</option><option value="USD">美元 USD</option><option value="EUR">欧元 EUR</option><option value="GBP">英镑 GBP</option><option value="JPY">日元 JPY</option></select></Field><Field label="计费周期"><select name="billing_period"><option value="month">每月</option><option value="year">每年</option><option value="usage">按量计费</option><option value="one_time">一次性</option><option value="free">无许可费</option></select></Field><Field label="适用版本"><input name="version" required placeholder="具体版本或核查范围" /></Field></div></>}
    {type === 'relation' && <><Field label="关联目标"><select name="target_entity_id" required><option value="">请选择关联目标</option>{entities.filter(entity => entity.id !== entityId).map(entity => <option key={entity.id} value={entity.id}>{entity.name}</option>)}</select></Field><Field label="关系类型"><select name="type"><option value="official_product">官方产品</option><option value="hosted_version">官方托管服务</option><option value="developed_by">开发 / 维护关系</option><option value="compatible_with">兼容关系</option><option value="alternative">同类替代</option><option value="candidate">候选关系</option></select></Field><div className="notice"><Info size={14} />关系先进入待复核状态，不能凭名称相似直接确认。</div></>}
    {type === 'source' && <><Field label="来源标识"><input name="id" required pattern="[a-zA-Z0-9_-]+" placeholder="official-docs" /></Field><Field label="来源名称"><input name="name" required /></Field><Field label="来源主页"><input name="url" type="url" required placeholder="https://…" /></Field><Field label="使用条款 URL（选填）"><input name="terms_url" type="url" placeholder="https://…" /></Field><Field label="采集方式"><select name="collection_method"><option value="manual">人工录入</option><option value="public_api">官方公开 API</option><option value="official_page">官方页面</option><option value="rss">RSS / Atom</option></select></Field><Field label="权限核查说明"><textarea name="reason" required rows={4} /></Field><div className="notice"><Info size={14} />新来源默认为停用、权限待审，不会自动发起外部采集。</div></>}
    {['event', 'assertion', 'edition', 'relation'].includes(type) && <fieldset className="editorial-evidence"><legend>关联原始证据</legend>{evidences.length ? evidences.map(evidence => <label key={evidence.id}><input type="checkbox" checked={evidenceIds.includes(evidence.id)} onChange={event => setEvidenceIds(previous => event.target.checked ? [...previous, evidence.id] : previous.filter(id => id !== evidence.id))} /><span>{evidence.title}<small>{evidence.review_status === 'published' ? '已核查发布' : '尚未核查发布'}</small></span><EvidenceButtons ids={[evidence.id]} records={[evidence]} /></label>) : <p className="muted">这个对象暂无证据，请先录入并审核原始出处。</p>}</fieldset>}
    <div className="form-actions"><Button type="button" onClick={onClose}>取消</Button><Button type="submit" variant="primary" busy={busy}>保存资料<Check size={15} /></Button></div>
  </form></Modal>;
}

createRoot(document.getElementById('root')).render(<React.StrictMode><App /></React.StrictMode>);
